defaultMessage = `Dear ${clientName},

Thank you for booking an interior design consultation with Good Interior Design Studio! We have received your request.${detailsBlock}

Our senior interior design team has reviewed your submission and we are eager to assist you with your project. Please let us know if your preferred date works for an in-person studio session or call, or suggest any alternative time that suits you.

Best Regards,
Good Interior Design Studio Executive Team`;

defaultMessage = `Dear ${clientName},

Thank you for reaching out to Good Interior Design Studio regarding "${msg.subject || msg.serviceType || 'your inquiry'}".${userMsgBlock}

We have reviewed your message and would love to assist you with your interior design needs. Please let us know your convenient time for a brief discussion or meeting.

Best Regards,
Good Interior Design Studio Executive Team`;
